import { NgModule } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatTooltipModule } from '@angular/material/tooltip';
import { BtnLink } from './btn-link/btn-link';
import { Btn } from './btn/btn';
import { NGX_NGB_Other_Module } from '@_modules/ngx-ngb-other.module';
import { AngularzModule } from '@_modules/angularz.module';

const component = [Btn, BtnLink];
const modules = [
  AngularzModule,
  NGX_NGB_Other_Module,
  MatButtonModule,
  MatIconModule,
  MatTooltipModule,
];

@NgModule({
  imports: [modules],
  exports: [component, modules],
  declarations: component,
})
export class UtilModule {}
